@startuml

class FurnitureLine {
  + Name : string
}

class Furniture {
  + Reference : string
  + SellingPrice : double
}

class ComponentType {
  + Code : int
  + ManufacturingPrice : double
  + Type : string
}

class Component {
  + ComponentType : ComponentType
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : string
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" *-- "*" Furniture
Furniture "1" -- "*" Component "1..*"
Furniture "1" -- "*" OrderLine
Order "1" -- "1" Store
Order "1" *-- "*" OrderLine
Store "1" -- "*" Order
OrderLine "*" -- "1" Furniture

@enduml

